        andBool (absFloat(F) *Float Int2Float(10 ^Int N, 53, 11)) <Float 4500000000000000.0
        andBool exponentFloat(F) >Int -900 [concrete]
  rule roundFN(F:Float, N:Int)
    => Int2Float(roundF(F *Float Int2Float(10 ^Int N, 53, 11)), 53, 11)
       /Float Int2Float(10 ^Int N, 53, 11) [owise, concrete]

// reference/src/semantics/int.k — MPY-INT
// Int cases of the operator dispatch; Python // and % are floored (pyMod).

module MPY-INT
  imports MPY-CORE

  rule applyUn("-", I:Int) => 0 -Int I

  rule applyBin("+",  I1:Int, I2:Int) => I1 +Int I2
  // Bool participates in int arithmetic (x += (a == b))
  rule applyBin("+",  I:Int, B:Bool) => I +Int #if B #then 1 #else 0 #fi
  rule applyBin("+",  B:Bool, I:Int) => #if B #then 1 #else 0 #fi +Int I
  // bool is a subtype of int: any Bool operand promotes to 0/1 and re-dispatches
  // to the Int cases (the "+" mixed cases above are kept, so "+" is excluded here
  // to avoid a duplicate rule — Bool + Bool still promotes via the Bool x Bool rule).
  rule applyBin(OP:String, B1:Bool, B2:Bool) => applyBin(OP, boolAsInt(B1), boolAsInt(B2))
       requires isArithOp(OP)
  rule applyBin(OP:String, B:Bool, I:Int)    => applyBin(OP, boolAsInt(B), I)
       requires isArithOp(OP) andBool OP =/=String "+"
  rule applyBin(OP:String, I:Int, B:Bool)    => applyBin(OP, I, boolAsInt(B))
       requires isArithOp(OP) andBool OP =/=String "+"
  rule applyBin("-",  I1:Int, I2:Int) => I1 -Int I2
  rule applyBin("*",  I1:Int, I2:Int) => I1 *Int I2
  rule applyBin("%",  I1:Int, I2:Int) => pyMod(I1, I2)
  rule applyBin("//", I1:Int, I2:Int) => (I1 -Int pyMod(I1, I2)) /Int I2
  rule applyBin("**", I1:Int, I2:Int) => I1 ^Int I2 requires I2 >=Int 0

  syntax Int ::= pyMod(Int, Int) [function]
  rule pyMod(I1:Int, I2:Int) => ((I1 %Int I2) +Int I2) %Int I2

  rule applyCmp("<",  I1:Int, I2:Int)   => I1 <Int  I2
  rule applyCmp("<=", I1:Int, I2:Int)   => I1 <=Int I2
  rule applyCmp(">",  I1:Int, I2:Int)   => I1 >Int  I2
  rule applyCmp(">=", I1:Int, I2:Int)   => I1 >=Int I2
  rule applyCmp("==", I1:Int, I2:Int)   => I1 ==Int I2
  rule applyCmp("!=", I1:Int, I2:Int)   => I1 =/=Int I2
endmodule
// reference/src/semantics/bool.k — MPY-BOOL
// Bool operator cases + the truthy boolean operations (not / and / or; and-or are
// value-returning short-circuit over any Vals, per Python).

module MPY-BOOL
  imports MPY-CORE

  rule applyUn("not", V:Val) => notBool truthy(V)

  rule applyCmp("==", B1:Bool, B2:Bool) => B1 ==Bool B2
  rule applyCmp("!=", B1:Bool, B2:Bool) => B1 =/=Bool B2

  // bool is a subtype of int: a Bool compared with an Int promotes to 0/1 and
  // re-dispatches to the Int comparison cases (True==1, False==0, True<2, ...).
  // The == / != Bool x Bool cases above are kept; only the four ordering ops are
  // promoted for Bool x Bool (to avoid duplicating the two rules above).
  rule applyCmp(OP:String, B:Bool, I:Int) => applyCmp(OP, boolAsInt(B), I)
       requires isEqOrdOp(OP)
  rule applyCmp(OP:String, I:Int, B:Bool) => applyCmp(OP, I, boolAsInt(B))
       requires isEqOrdOp(OP)
  rule applyCmp(OP:String, B1:Bool, B2:Bool) => applyCmp(OP, boolAsInt(B1), boolAsInt(B2))
       requires isOrdOp(OP)

  // ==== Bool…5036 tokens truncated… OP ==String "not in"
       [priority(40)]

  rule <k> UnaryOp(OP:String, ref(H:Int)) => UnaryOp(OP, V) ... </k>
       <heap> ... H |-> V:Val ... </heap>
       [priority(40)]
endmodule
